fn rebuildResourcePathMatcher(&mut self) -> Result<(), String> {
    self.resourcePathMatcher = if self.resourcePaths.is_empty() {
        None
    } else {
        Some(aho_corasick::AhoCorasick::new(
            self.resourcePaths.iter().map(|(source, _)| source.as_str()),
