    };
    Ok(())
}

fn rewriteMessageContent(&self, content: &str) -> String {
    let Some(matcher) = &self.resourcePathMatcher else { return content.to_string(); };
    // Scan the original text once for all archived paths. The former loop
    // scanned AND copied every message once per resource, even on a miss;
    // thousands of files made the unreported post-parse phase look stuck.
    let mut matches = matcher.find_overlapping_iter(content).filter(|found| {
        content[found.end()..].chars().next().map_or(true, |value| {
            value.is_whitespace() || matches!(value, '\'' | '"' | '<' | '>' | ')' | ']' | '}')
        })
    }).collect::<Vec<_>>();
    if matches.is_empty() { return content.to_string(); }
    // Keep complete file:// aliases and longer filenames ahead of their
    // embedded/shorter matches, after applying the actual path boundary.
    matches.sort_unstable_by(|left, right| left.start().cmp(&right.start())
        .then_with(|| right.end().cmp(&left.end()))
        .then_with(|| left.pattern().as_usize().cmp(&right.pattern().as_usize())));
    let mut output = String::with_capacity(content.len());
    let mut copied = 0;
    for found in matches {
        if found.start() < copied { continue; }
        output.push_str(&content[copied..found.start()]);
        output.push_str(&self.resourcePaths[found.pattern().as_usize()].1);
        copied = found.end();
    }
    output.push_str(&content[copied..]);
    // Inserted destinations are never scanned again as legacy sources.
    output
}

